// ============================================================
// PANGI DB MANAGER — Query Factory v1.0.0
// Sistema NOVA · SAGE · ATLAS + WhatsApp
// Erick Del Piero | Marzo 2026
//
// OPERACIONES DISPONIBLES:
//   getOrCreateUser       | phone, name?, language?
//   updateUserActivity    | userId, name?
//   getActiveSession      | userId
//   createSession         | userId, agent?, state?, context?
//   updateSession         | sessionId, agent?, state?, context?
//   expireSession         | sessionId
//   saveMessage           | userId, sessionId?, agent, role, message, messageType?
//   getConversationHistory| userId, limit?, sessionId?
//   saveMedicalIntake     | userId, sessionId?, specialty, procedureName?, collectedData?, missingItems?, score?
//   updateMedicalIntake   | intakeId, collectedData?, missingItems?, score?, status?
//   getMedicalIntake      | sessionId? | userId?
//   getProcedure          | procedureKey
//   getProceduresBySpecialty | specialty
//   saveQuote             | userId, intakeId?, destinationCity, destinationCountry, procedureCost, ...
//   getQuotes             | userId, intakeId?
//   getDestinations       | country?
//   logHandoff            | userId, sessionId?, fromAgent, toAgent, reason?, contextSnapshot?
//   cleanupExpiredSessions| (sin parámetros)
// ============================================================

const input = $input.first().json;
const operation = input.operation;
const params = input.params || {};

// ── VALIDACIÓN BÁSICA ──────────────────────────────────────
// Passthrough para operaciones internas que no requieren consulta a DB
if (operation === '__skip__') {
  return [{ json: {
    success:      true,
    operation:    '__skip__',
    sql:          'SELECT 1 AS skip_passthrough',
    _passthrough: true,
    _meta: { timestamp: new Date().toISOString(), source: 'passthrough_skip' }
  }}];
}
if (!operation || typeof operation !== 'string') {
  return [{ json: {
    success: false,
    error: 'MISSING_OPERATION',
    message: 'El campo operation es requerido y debe ser string.',
    data: null, operation: null, sql: null
  }}];
}

const ALLOWED_OPERATIONS = [
  'getOrCreateUser', 'updateUserActivity',
  'getActiveSession', 'createSession', 'updateSession', 'expireSession',
  'saveMessage', 'checkMessageDedup', 'getConversationHistory',
  'saveMedicalIntake', 'updateMedicalIntake', 'getMedicalIntake',
  'getProcedure', 'getProceduresBySpecialty',
  'saveQuote', 'getQuotes',
  'getDestinations',
  'logHandoff', 'cleanupExpiredSessions'
];

if (!ALLOWED_OPERATIONS.includes(operation)) {
  return [{ json: {
    success: false,
    error: 'UNKNOWN_OPERATION',
    message: `Operación desconocida: "${operation}". Válidas: ${ALLOWED_OPERATIONS.join(', ')}`,
    data: null, operation, sql: null
  }}];
}

// ── SANITIZADOR SQL ────────────────────────────────────────
// Protege contra SQL injection para todos los valores de entrada.
// Todos los valores externos pasan por s() o si() antes de ir al SQL.
const s = (val) => {
  if (val === null || val === undefined) return 'NULL';
  if (typeof val === 'boolean') return val ? 'TRUE' : 'FALSE';
  if (typeof val === 'number') return isFinite(val) ? String(val) : 'NULL';
  if (typeof val === 'object') {
    const j = JSON.stringify(val).replace(/'/g, `''`);
    return `'${j}'::jsonb`;
  }
  const str = String(val).replace(/'/g, `''`);
  return `'${str}'`;
};

// Entero seguro — solo permite números enteros positivos
const si = (val) => {
  const n = parseInt(val, 10);
  return isNaN(n) || n < 0 ? 'NULL' : String(n);
};

let sql = '';

try {
  switch (operation) {

    // ════════════════════════════════════════════════════════
    // USUARIOS
    // ════════════════════════════════════════════════════════

    case 'getOrCreateUser': {
      const { phone, name = null, language = 'es' } = params;
      if (!phone) throw new Error('"phone" es requerido para getOrCreateUser');
      const validLangs = ['es', 'en', 'pt'];
      const safeLang = validLangs.includes(language) ? language : 'es';
      sql = `INSERT INTO users (phone, name, language, first_contact, last_activity)
        VALUES (${s(phone)}, ${s(name)}, ${s(safeLang)}, NOW(), NOW())
        ON CONFLICT (phone) DO UPDATE SET
          last_activity = NOW(),
          name = COALESCE(EXCLUDED.name, users.name)
        RETURNING *`;
      break;
    }

    case 'updateUserActivity': {
      const { userId, name = null } = params;
      if (!userId) throw new Error('"userId" es requerido para updateUserActivity');
      const nameClause = name !== null ? `, name = ${s(name)}` : '';
      sql = `UPDATE users
        SET last_activity = NOW()${nameClause}
        WHERE id = ${si(userId)}
        RETURNING id, phone, name, language, last_activity`;
      break;
    }

    // ════════════════════════════════════════════════════════
    // SESIONES
    // ════════════════════════════════════════════════════════

    case 'getActiveSession': {
      const { userId } = params;
      if (!userId) throw new Error('"userId" es requerido para getActiveSession');
      // Prioridad: SAGE y ATLAS sobre NOVA. Dentro de cada grupo, más reciente primero.
      // Esto garantiza que aunque haya múltiples sesiones, siempre se recupera
      // la sesión del agente especialista si existe.
      sql = `SELECT * FROM sessions
        WHERE user_id = ${si(userId)}
          AND state != 'expired'
          AND expires_at > NOW()
        ORDER BY
          CASE WHEN active_agent IN ('SAGE', 'ATLAS') THEN 0 ELSE 1 END ASC,
          updated_at DESC
        LIMIT 1`;
      break;
    }

    case 'createSession': {
      const { userId, agent = 'NOVA', state = 'initial', context = {} } = params;
      if (!userId) throw new Error('"userId" es requerido para createSession');
      const validAgents = ['NOVA', 'SAGE', 'ATLAS'];
      const safeAgent = validAgents.includes(agent) ? agent : 'NOVA';

      // CTE: solo expira sesiones ZOMBIE (tiempo expirado pero state != 'expired').
      // NO toca sesiones activas válidas — esas se manejan por ON CONFLICT.
      // Si el INSERT falla por race condition (otra ejecución paralela ya creó la sesión),
      // ON CONFLICT recupera la sesión existente en lugar de explotar.
      sql = `WITH cleanup AS (
          UPDATE sessions
          SET state = 'expired', updated_at = NOW()
          WHERE user_id = ${si(userId)}
            AND state != 'expired'
            AND expires_at < NOW()
        )
        INSERT INTO sessions
            (user_id, active_agent, state, context, created_at, updated_at, expires_at)
          VALUES (
            ${si(userId)}, ${s(safeAgent)}, ${s(state)}, ${s(context)},
            NOW(), NOW(), NOW() + INTERVAL '24 hours'
          )
        ON CONFLICT (user_id) WHERE state != 'expired'
        DO UPDATE SET
          updated_at   = NOW(),
          expires_at   = NOW() + INTERVAL '24 hours'
        RETURNING *`;
      break;
    }

    case 'updateSession': {
      const { sessionId, agent, state, context } = params;
      // Validación estricta: sessionId debe ser un entero positivo válido.
      // NaN, 0, null y undefined son rechazados explícitamente aquí
      // porque !NaN = true pero Number.isInteger(NaN) = false.
      if (!sessionId || !Number.isInteger(Number(sessionId)) || Number(sessionId) <= 0) {
        throw new Error(`"sessionId" inválido para updateSession: recibido "${sessionId}". Debe ser un entero positivo.`);
      }
      if (!sessionId) throw new Error('"sessionId" es requerido para updateSession');
      const setParts = [];
      if (agent) {
        const validAgents = ['NOVA', 'SAGE', 'ATLAS'];
        const safeAgent = validAgents.includes(agent) ? agent : 'NOVA';
        setParts.push(`active_agent = ${s(safeAgent)}`);
      }
      if (state) setParts.push(`state = ${s(state)}`);
      if (context !== undefined) setParts.push(`context = ${s(context)}`);
      setParts.push(`updated_at = NOW()`);
      setParts.push(`expires_at = NOW() + INTERVAL '24 hours'`);
      sql = `UPDATE sessions
        SET ${setParts.join(', ')}
        WHERE id = ${si(sessionId)}
        RETURNING *`;
      break;
    }

    case 'expireSession': {
      const { sessionId } = params;
      if (!sessionId) throw new Error('"sessionId" es requerido para expireSession');
      sql = `UPDATE sessions
        SET state = 'expired', updated_at = NOW()
        WHERE id = ${si(sessionId)}
        RETURNING id, state, updated_at`;
      break;
    }

    // ════════════════════════════════════════════════════════
    // MENSAJES
    // ════════════════════════════════════════════════════════
    case 'checkMessageDedup': {
      const { dedupKey } = params;
      if (!dedupKey) throw new Error('"dedupKey" es requerido para checkMessageDedup');
      // Test-and-set atómico por restricción UNIQUE — imposible de ganar en carrera:
      // 1 fila = mensaje nuevo · 0 filas = duplicado (álbum o retry de webhook)
      sql = `INSERT INTO message_dedup (dedup_key)
        VALUES (${s(dedupKey)})
        ON CONFLICT (dedup_key) DO NOTHING
        RETURNING dedup_key, created_at`;
      break;
    }

    case 'saveMessage': {
      const { userId, sessionId = null, agent, role, message, messageType = 'text' } = params;
      if (!userId) throw new Error('"userId" es requerido para saveMessage');
      if (!agent) throw new Error('"agent" es requerido para saveMessage');
      if (!role) throw new Error('"role" es requerido para saveMessage');
      if (!message) throw new Error('"message" es requerido para saveMessage');
      const validRoles = ['user', 'assistant', 'system'];
      const validAgents = ['NOVA', 'SAGE', 'ATLAS', 'ROUTER'];
      const validTypes = ['text', 'image', 'audio', 'document', 'button_reply'];
      const safeRole = validRoles.includes(role) ? role : 'user';
      const safeAgent = validAgents.includes(agent) ? agent : 'NOVA';
      const safeType = validTypes.includes(messageType) ? messageType : 'text';
      sql = `INSERT INTO conversation_history
          (user_id, session_id, agent, role, message, message_type, created_at)
        VALUES (
          ${si(userId)}, ${sessionId ? si(sessionId) : 'NULL'},
          ${s(safeAgent)}, ${s(safeRole)}, ${s(message)}, ${s(safeType)},
          NOW()
        )
        RETURNING id, created_at`;
      break;
    }

    case 'getConversationHistory': {
      const { userId, limit = 20, sessionId = null } = params;
      if (!userId) throw new Error('"userId" es requerido para getConversationHistory');
      const safeLimit = Math.min(Math.max(parseInt(limit) || 20, 1), 100);
      if (sessionId) {
        sql = `SELECT * FROM conversation_history
          WHERE user_id = ${si(userId)} AND session_id = ${si(sessionId)}
          ORDER BY created_at ASC
          LIMIT ${safeLimit}`;
      } else {
        sql = `SELECT * FROM conversation_history
          WHERE user_id = ${si(userId)}
          ORDER BY created_at DESC
          LIMIT ${safeLimit}`;
      }
      break;
    }

    // ════════════════════════════════════════════════════════
    // SAGE — MEDICAL INTAKE
    // ════════════════════════════════════════════════════════

    case 'saveMedicalIntake': {
      const {
        userId, sessionId = null, specialty,
        procedureName = null, collectedData = {},
        missingItems = [], score = 0
      } = params;
      if (!userId) throw new Error('"userId" es requerido para saveMedicalIntake');
      if (!specialty) throw new Error('"specialty" es requerido para saveMedicalIntake');
      const safeScore = Math.min(Math.max(parseInt(score) || 0, 0), 100);
      sql = `INSERT INTO medical_intake
          (user_id, session_id, specialty, procedure_name, collected_data,
           missing_items, completeness_score, status, created_at, updated_at)
        VALUES (
          ${si(userId)}, ${sessionId ? si(sessionId) : 'NULL'},
          ${s(specialty)}, ${s(procedureName)}, ${s(collectedData)},
          ${s(missingItems)}, ${safeScore}, 'in_progress',
          NOW(), NOW()
        )
        RETURNING *`;
      break;
    }

    case 'updateMedicalIntake': {
      const { intakeId, collectedData, missingItems, score, status } = params;
      if (!intakeId) throw new Error('"intakeId" es requerido para updateMedicalIntake');
      const setParts = [];
      if (collectedData !== undefined) setParts.push(`collected_data = ${s(collectedData)}`);
      if (missingItems !== undefined) setParts.push(`missing_items = ${s(missingItems)}`);
      if (score !== undefined) {
        const safeScore = Math.min(Math.max(parseInt(score) || 0, 0), 100);
        setParts.push(`completeness_score = ${safeScore}`);
      }
      if (status) {
        const validStatuses = ['in_progress', 'complete', 'submitted', 'cancelled'];
        const safeStatus = validStatuses.includes(status) ? status : 'in_progress';
        setParts.push(`status = ${s(safeStatus)}`);
      }
      if (!setParts.length) throw new Error('Al menos un campo debe enviarse para actualizar en updateMedicalIntake');
      setParts.push('updated_at = NOW()');
      sql = `UPDATE medical_intake
        SET ${setParts.join(', ')}
        WHERE id = ${si(intakeId)}
        RETURNING *`;
      break;
    }

    case 'getMedicalIntake': {
      const { sessionId, userId } = params;
      if (!sessionId && !userId) throw new Error('"sessionId" o "userId" son requeridos para getMedicalIntake');
      if (sessionId) {
        sql = `SELECT * FROM medical_intake
          WHERE session_id = ${si(sessionId)}
          ORDER BY created_at DESC LIMIT 1`;
      } else {
        sql = `SELECT * FROM medical_intake
          WHERE user_id = ${si(userId)}
          ORDER BY created_at DESC LIMIT 5`;
      }
      break;
    }

    // ════════════════════════════════════════════════════════
    // KNOWLEDGE BASE
    // ════════════════════════════════════════════════════════

    case 'getProcedure': {
      const { procedureKey } = params;
      if (!procedureKey) throw new Error('"procedureKey" es requerido para getProcedure');
      sql = `SELECT * FROM knowledge_base
        WHERE procedure_key = ${s(procedureKey)} AND is_active = TRUE
        LIMIT 1`;
      break;
    }

    case 'getProceduresBySpecialty': {
      const { specialty } = params;
      if (!specialty) throw new Error('"specialty" es requerido para getProceduresBySpecialty');
      const validSpecialties = ['dental', 'plastic_surgery'];
      if (!validSpecialties.includes(specialty)) {
        throw new Error(`Especialidad inválida: "${specialty}". Válidas: ${validSpecialties.join(', ')}`);
      }
      sql = `SELECT id, specialty, procedure_name, procedure_key, typical_recovery_days, sage_intro_message
        FROM knowledge_base
        WHERE specialty = ${s(specialty)} AND is_active = TRUE
        ORDER BY procedure_name ASC`;
      break;
    }

    // ════════════════════════════════════════════════════════
    // COTIZACIONES
    // ════════════════════════════════════════════════════════

    case 'saveQuote': {
      const {
        userId, intakeId = null,
        destinationCity, destinationCountry, procedureCost,
        doctorName = null, clinicName = null,
        doctorExperience = null, notes = null, quoteData = {}
      } = params;
      if (!userId) throw new Error('"userId" es requerido para saveQuote');
      if (!destinationCity) throw new Error('"destinationCity" es requerido para saveQuote');
      if (!destinationCountry) throw new Error('"destinationCountry" es requerido para saveQuote');
      if (procedureCost === undefined || procedureCost === null) throw new Error('"procedureCost" es requerido para saveQuote');
      const safeCost = parseFloat(procedureCost);
      if (isNaN(safeCost) || safeCost < 0) throw new Error('"procedureCost" debe ser un número positivo');
      sql = `INSERT INTO quotes_comparison
          (user_id, intake_id, destination_city, destination_country, procedure_cost,
           doctor_name, clinic_name, doctor_experience_years, additional_notes, quote_data, created_at)
        VALUES (
          ${si(userId)}, ${intakeId ? si(intakeId) : 'NULL'},
          ${s(destinationCity)}, ${s(destinationCountry)}, ${safeCost},
          ${s(doctorName)}, ${s(clinicName)},
          ${doctorExperience ? si(doctorExperience) : 'NULL'},
          ${s(notes)}, ${s(quoteData)}, NOW()
        )
        RETURNING *`;
      break;
    }

    case 'getQuotes': {
      const { userId, intakeId = null } = params;
      if (!userId) throw new Error('"userId" es requerido para getQuotes');
      if (intakeId) {
        sql = `SELECT
            q.*,
            d.avg_flight_cost_usd,
            d.avg_hotel_cost_per_night_usd,
            d.avg_recovery_days_dental,
            d.avg_recovery_days_plastic,
            d.climate_type,
            d.languages AS destination_languages,
            d.visa_required_us,
            d.notes AS destination_notes
          FROM quotes_comparison q
          LEFT JOIN atlas_destinations d
            ON d.city = q.destination_city AND d.country = q.destination_country
          WHERE q.user_id = ${si(userId)} AND q.intake_id = ${si(intakeId)}
          ORDER BY q.procedure_cost ASC`;
      } else {
        sql = `SELECT
            q.*,
            d.avg_flight_cost_usd,
            d.avg_hotel_cost_per_night_usd,
            d.avg_recovery_days_dental,
            d.avg_recovery_days_plastic
          FROM quotes_comparison q
          LEFT JOIN atlas_destinations d
            ON d.city = q.destination_city AND d.country = q.destination_country
          WHERE q.user_id = ${si(userId)}
          ORDER BY q.created_at DESC
          LIMIT 10`;
      }
      break;
    }

    // ════════════════════════════════════════════════════════
    // ATLAS — DESTINOS
    // ════════════════════════════════════════════════════════

    case 'getDestinations': {
      const { country = null } = params;
      if (country) {
        sql = `SELECT * FROM atlas_destinations
          WHERE is_active = TRUE AND country = ${s(country)}
          ORDER BY avg_flight_cost_usd ASC`;
      } else {
        sql = `SELECT * FROM atlas_destinations
          WHERE is_active = TRUE
          ORDER BY country ASC, avg_flight_cost_usd ASC`;
      }
      break;
    }

    // ════════════════════════════════════════════════════════
    // SISTEMA
    // ════════════════════════════════════════════════════════

    case 'logHandoff': {
      const { userId, sessionId = null, fromAgent, toAgent, reason = null, contextSnapshot = {} } = params;
      if (!userId) throw new Error('"userId" es requerido para logHandoff');
      if (!fromAgent) throw new Error('"fromAgent" es requerido para logHandoff');
      if (!toAgent) throw new Error('"toAgent" es requerido para logHandoff');
      sql = `INSERT INTO agent_handoffs
          (user_id, session_id, from_agent, to_agent, reason, context_snapshot, created_at)
        VALUES (
          ${si(userId)}, ${sessionId ? si(sessionId) : 'NULL'},
          ${s(fromAgent)}, ${s(toAgent)}, ${s(reason)}, ${s(contextSnapshot)},
          NOW()
        )
        RETURNING *`;
      break;
    }

    case 'cleanupExpiredSessions': {
      sql = `SELECT cleanup_expired_sessions() AS result`;
      break;
    }

  }

  return [{ json: {
    success: true,
    operation,
    sql,
    _meta: {
      timestamp: new Date().toISOString(),
      paramsReceived: Object.keys(params)
    }
  }}];

} catch (err) {
  return [{ json: {
    success: false,
    error: 'QUERY_BUILD_ERROR',
    message: err.message,
    operation,
    sql: null,
    _meta: { timestamp: new Date().toISOString() }
  }}];
}

// ============================================================
// FORMAT FINAL RESPONSE v1.0.2 — Pangi DB Manager
// Fix: detección robusta de passthroughs via indicadores positivos.
// En N8N v1.116, alwaysOutputData genera { "success": true } cuando
// PostgreSQL retorna 0 filas — NO el item del nodo anterior.
// La estrategia correcta: verificar presencia de campos propios
// de filas reales, no ausencia de campos del build node.
// ============================================================

const allItems  = $input.all();
const buildNode = $('🔍 Validar y Construir Query').first().json;
const operation = buildNode.operation || 'unknown';
const timestamp = new Date().toISOString();

// ── DETECTAR ERROR DE POSTGRES ────────────────────────────
const first    = (allItems[0] || { json: {} }).json;
const pgError  = first.errorMessage || first.message;
const pgErrObj = first.error;
// DESPUÉS — detecta tanto errores nativos de Postgres como NodeOperationError de N8N
const isPostgresError = !!pgError && (
  // Error nativo de Postgres (tiene code: '23505', '42P01', etc.)
  (typeof pgErrObj === 'object' && pgErrObj !== null && pgErrObj.code) ||
  // NodeOperationError de N8N (wrappea errores de Postgres sin code)
  (typeof pgErrObj === 'object' && pgErrObj !== null && (
    pgErrObj.name === 'NodeOperationError' ||
    pgErrObj.description !== undefined ||
    pgErrObj.level !== undefined
  ))
);

if (isPostgresError) {
  return [{ json: {
    success:   false,
    error:     'DB_QUERY_ERROR',
    message:   pgError || 'Error ejecutando query en PostgreSQL',
    operation,
    data:      null,
    count:     0,
    _meta: {
      timestamp,
      source:       'postgres_error',
      pgCode:       pgErrObj ? (pgErrObj.code || pgErrObj.level || null) : null,
      pgDetail:     pgErrObj ? (pgErrObj.description || null) : null,
      sql_preview:  buildNode.sql ? buildNode.sql.substring(0, 120) + '...' : null
    }
  }}];
}

// ── FILTRO ROBUSTO: SOLO FILAS REALES DE DB ───────────────
// Estrategia: en lugar de detectar passthroughs (que varían por versión
// de N8N), detectamos POSITIVAMENTE filas reales usando campos que
// SIEMPRE están presentes en nuestras tablas.
//
// Passthroughs conocidos:
//   { "success": true }              — N8N v1.116 alwaysOutputData
//   { "sql": "...", "operation": }   — build node passthrough (versiones anteriores)
//
// Filas reales siempre tienen al menos uno de:
//   id (number)       — todas nuestras tablas tienen PK id
//   created_at        — tablas con timestamp
//   result            — función cleanup_expired_sessions()
//   country           — atlas_destinations
//   procedure_key     — knowledge_base

const isRealRow = (j) => {
  if (!j || typeof j !== 'object') return false;
  if (j.sql !== undefined)         return false; // build node passthrough
  return (
    typeof j.id           === 'number' ||
    typeof j.created_at   === 'string' ||
    typeof j.result       !== 'undefined' ||
    typeof j.country      === 'string' ||
    typeof j.procedure_key === 'string'
  );
};

// Parsear campos JSONB que pueden llegar como string
const JSONB_FIELDS = [
  'context', 'collected_data', 'missing_items',
  'quote_data', 'context_snapshot', 'required_info',
  'critical_questions', 'required_exams', 'metadata'
];

const rows = allItems
  .filter(item => isRealRow(item.json || {}))
  .map(item => {
    const row = { ...item.json };
    JSONB_FIELDS.forEach(field => {
      if (row[field] && typeof row[field] === 'string') {
        try { row[field] = JSON.parse(row[field]); } catch(e) {}
      }
    });
    return row;
  });

return [{ json: {
  success:   true,
  operation,
  data:      rows,
  count:     rows.length,
  phi_stripped: true,
  _meta: {
    timestamp,
    source:      rows.length > 0 ? 'db_success' : 'db_empty',
    paramsUsed:  buildNode._meta ? buildNode._meta.paramsReceived : []
  }
}}];

// ============================================================
// VALIDATION ERROR RESPONSE — Pangi DB Manager
// Se ejecuta cuando la validación o construcción del query falla.
// Devuelve el mismo schema estándar que los demás nodos.
// ============================================================

const input = $input.first().json;

return [{ json: {
  success: false,
  error: input.error || 'VALIDATION_ERROR',
  message: input.message || 'Error de validación en DB Manager',
  operation: input.operation || null,
  data: null,
  count: 0,
  _meta: {
    timestamp: new Date().toISOString(),
    source: 'validation_error'
  }
}}];
